import{_ as s,o,c as n,af as a}from"./chunks/framework.B28LkSoM.js";const h=JSON.parse('{"title":"Maven是什么与核心概念","description":"Maven 入门第一问——它是什么、能解决哪三件事（依赖管理、项目构建、统一项目结构），以及 POM、依赖管理模型、构建生命周期与阶段、插件、仓库这几张核心概念图怎么串起来","frontmatter":{"title":"Maven是什么与核心概念","published":"2026-09-29T00:00:00.000Z","description":"Maven 入门第一问——它是什么、能解决哪三件事（依赖管理、项目构建、统一项目结构），以及 POM、依赖管理模型、构建生命周期与阶段、插件、仓库这几张核心概念图怎么串起来","tags":["JavaWeb","Maven","后端"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-23-maven-what-is.webp","order":23,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/23-Maven是什么与核心概念.md","filePath":"posts/学习文档/JavaWeb学习笔记/23-Maven是什么与核心概念.md"}'),e={name:"posts/学习文档/JavaWeb学习笔记/23-Maven是什么与核心概念.md"};function r(d,t,g,i,l,c){return o(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1790640000000"},[...t[0]||(t[0]=[a(`<p>前面 22 篇做的都是<strong>前端</strong>（HTML/CSS/JS/Vue），页面写完就能在浏览器里看到。从这一篇起进入<strong>后端 Web 基础</strong>，第一件事不是写代码，而是先把&quot;<strong>管理和构建 Java 项目的工具</strong>&quot;装上——这就是 Maven。</p><p>这一章（PPT 第 15 页给的路线图）分四块：<strong>Maven 概述</strong>、<strong>IDEA 集成 Maven</strong>、<strong>依赖管理</strong>、<strong>单元测试</strong>，后面还有一块 Maven 进阶（分模块设计、继承、聚合、私服）。这一篇只讲第一块的<strong>前半部分</strong>：Maven 是什么、有哪三大作用、几张核心概念图怎么读、仓库是什么。</p><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>这一章的目录页（PPT 第 14、15 页）把内容分成两层：<strong>Maven 核心</strong> = Maven 概述 / IDEA 集成 Maven / 依赖管理 / 单元测试；<strong>Maven 进阶</strong> = 分模块设计 / 继承 / 聚合 / 私服。&quot;Maven 概述&quot;里只有两节：<strong>介绍</strong>（这一篇）和<strong>安装</strong>（下一篇）。</p></div><h2 id="什么是-maven" tabindex="-1">什么是 Maven <a class="header-anchor" href="#什么是-maven" aria-label="Permalink to &quot;什么是 Maven&quot;">​</a></h2><p>PPT 上的定义分两句，第一句最好记：</p><blockquote><p><strong>Maven 是一款用于管理和构建 Java 项目的工具，是 Apache 旗下的一个开源项目。</strong></p><p><strong>Apache Maven 是一个项目管理和构建工具，它基于项目对象模型（POM）的概念，通过一小段描述信息来管理项目的构建。</strong></p></blockquote><p>拆开看这句话里的三个关键词：</p><table tabindex="0"><thead><tr><th>关键词</th><th>说的是什么</th></tr></thead><tbody><tr><td><strong>管理和构建</strong></td><td>Maven 有两件事：管<strong>依赖</strong>（项目要用到的第三方 jar 包）、跑<strong>构建</strong>（编译、测试、打包、发布）</td></tr><tr><td><strong>基于项目对象模型（POM）</strong></td><td>Maven 眼里一个项目就是一个&quot;对象&quot;，用根目录下的 <strong><code>pom.xml</code></strong> 这个文件来描述它——Maven 读这个文件干活</td></tr><tr><td><strong>一小段描述信息</strong></td><td>要你写的其实很少：依赖的坐标、打包方式、插件配置，几行就够</td></tr></tbody></table><p>关于背后的组织，PPT 专门介绍了两句：</p><ul><li><strong>Apache 软件基金会</strong>：成立于 <strong>1999 年 7 月</strong>，是目前世界上<strong>最大、最受欢迎的开源软件基金会</strong>，也是一个专门为支持开源项目而生的<strong>非盈利性组织</strong>；它的开源项目列表在 &lt;<a href="https://www.apache.org/index.html#projects-list" target="_blank" rel="noreferrer">https://www.apache.org/index.html#projects-list</a>&gt;。</li><li>Maven 自己的官网是 <strong>&lt;<a href="http://maven.apache.org/" target="_blank" rel="noreferrer">http://maven.apache.org/</a>&gt;</strong>。</li></ul><p>Maven 到底有多主流？PPT 用一张统计图说明问题——<strong>Java 项目构建工具的使用率里 Maven 占了 64%</strong>，是绝对主流：</p><p><img src="https://img.tsh520.cn/file/blog/article/13-Maven%E4%BD%BF%E7%94%A8%E7%8E%87%E7%BB%9F%E8%AE%A1.jpg" alt="Maven使用率统计"><em>图：构建工具使用率统计（PPT 第 13 页）——Maven 64%、Gradle 25%、Ant 6%、SBT 2%、None 2%、Other 1%，所以这门课教的是 Maven</em></p><h2 id="maven-的三大作用" tabindex="-1">Maven 的三大作用 <a class="header-anchor" href="#maven-的三大作用" aria-label="Permalink to &quot;Maven 的三大作用&quot;">​</a></h2><p>PPT 反复用同一页（第 5、7、10、12 页各有一次）把 Maven 的作用归纳成三条，每次展开讲一条：</p><table tabindex="0"><thead><tr><th>作用</th><th>PPT 的原话</th><th>解决什么问题</th></tr></thead><tbody><tr><td><strong>依赖管理</strong></td><td>方便快捷的管理项目依赖的资源（<strong>jar 包</strong>）</td><td>不用再手动下载 jar 包、手动拷进项目、缺一个补一个</td></tr><tr><td><strong>项目构建</strong></td><td>标准化的跨平台（<strong>Linux、Windows、MacOS</strong>）的<strong>自动化项目构建</strong>方式</td><td>编译、测试、打包、发布不用手工点，也不依赖某个操作系统或某个 IDE</td></tr><tr><td><strong>统一项目结构</strong></td><td>提供<strong>标准、统一</strong>的项目结构</td><td>不同 IDE 各搞一套目录，换一个工具就要重新认路</td></tr></tbody></table><p>第 18 页换了个顺序再说一遍（&quot;方便的依赖管理、标准的项目构建流程、统一的项目结构&quot;），指的还是这三件事。</p><h3 id="作用一-依赖管理" tabindex="-1">作用一：依赖管理 <a class="header-anchor" href="#作用一-依赖管理" aria-label="Permalink to &quot;作用一：依赖管理&quot;">​</a></h3><p><strong>依赖</strong>就是当前项目运行所需要的 <strong>jar 包</strong>。没有 Maven 的时候，你得自己去网上找 jar、下载、往项目里放；Maven 把这件事变成&quot;<strong>在 <code>pom.xml</code> 里写一段坐标描述</strong>&quot;：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    &lt;!-- 引入 commons-io 这个依赖：只要写出它的坐标，Maven 自己去下载并管好 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;commons-io&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;commons-io&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;2.11.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>写完之后点一下刷新，Maven 就会把 jar 包下载到<strong>本地仓库</strong>并挂到项目上（这一篇后面讲仓库，具体下载机制在&quot;依赖管理&quot;那一篇）。PPT 第 6 页配的图正是&quot;<strong>项目里那些第三方的 jar 包</strong>&quot;：</p><p><img src="https://img.tsh520.cn/file/blog/article/06-%E4%BE%9D%E8%B5%96%E7%AE%A1%E7%90%86%E7%9A%84jar%E5%8C%85.jpg" alt="依赖管理的jar包"><em>图：PPT 第 6 页讲&quot;依赖管理&quot;时配的项目结构——项目里除了 src 之外还有专门放 jar 包的 lib 目录（老做法是手动往里拷 jar）；Maven 要接管的就是这些&quot;别人写好的资源&quot;</em></p><h3 id="作用二-项目构建" tabindex="-1">作用二：项目构建 <a class="header-anchor" href="#作用二-项目构建" aria-label="Permalink to &quot;作用二：项目构建&quot;">​</a></h3><p><strong>构建</strong>指的是把源码变成能跑起来的东西这一整套动作。PPT 第 8、9 页把它拆成四步，并在第 9 页补上了对应的英文名（就是后面敲的命令）：</p><table tabindex="0"><thead><tr><th>构建动作</th><th>英文（命令里的阶段名）</th><th>干了什么</th></tr></thead><tbody><tr><td>编译</td><td><strong>compile</strong></td><td>把 <code>.java</code> 源码编译成 <code>.class</code> 字节码文件</td></tr><tr><td>测试</td><td><strong>test</strong></td><td>运行单元测试，检查代码对不对</td></tr><tr><td>打包</td><td><strong>package</strong></td><td>把编译结果打成可以分发的包（<strong>jar</strong>、war 等）</td></tr><tr><td>发布</td><td><strong>deploy</strong></td><td>把包发布出去，供别人或别的项目使用</td></tr></tbody></table><p>PPT 特意加了两个修饰词，这才是 Maven 的价值所在：</p><ul><li><strong>标准化</strong>：所有 Maven 项目都是同一套动作、同一套命令，不看 IDE 脸色；</li><li><strong>跨平台（Linux、Windows、MacOS）</strong>：同一套命令三种操作系统下都这么敲；配上&quot;自动化&quot;，就不用再手工点&quot;编译→运行→打包&quot;。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>这四个动作在命令行里就是 <code>mvn compile</code>、<code>mvn test</code>、<code>mvn package</code>、<code>mvn deploy</code> 这样一条条命令。为什么敲 <code>mvn package</code> 会连编译和测试一起做？这属于<strong>构建生命周期</strong>的规则，后面专门讲生命周期的那一篇会说清。</p></div><h3 id="作用三-统一项目结构" tabindex="-1">作用三：统一项目结构 <a class="header-anchor" href="#作用三-统一项目结构" aria-label="Permalink to &quot;作用三：统一项目结构&quot;">​</a></h3><p>PPT 第 11 页把三种 IDE 摆在一起做对比：<strong>Eclipse、MyEclipse、IntelliJ IDEA</strong> 各有一套目录习惯，同样一个 Java 项目，换个工具打开目录长得完全不一样：</p><p><img src="https://img.tsh520.cn/file/blog/article/11-Eclipse%E9%A1%B9%E7%9B%AE%E7%BB%93%E6%9E%84.jpg" alt="Eclipse项目结构"><em>图：Eclipse 里的项目（PPT 第 11 页）——左边是 IDE 视图（<code>src</code> 下挂着包和类），右边是磁盘上的真实目录，多出 <code>bin</code>、<code>.settings</code>、<code>.classpath</code>、<code>.project</code> 这些 Eclipse 自己的东西</em></p><p><img src="https://img.tsh520.cn/file/blog/article/11-IDEA%E9%A1%B9%E7%9B%AE%E7%BB%93%E6%9E%84.jpg" alt="IDEA项目结构"><em>图：IntelliJ IDEA 里的同一个项目（PPT 第 11 页）——磁盘上就只有 <code>src</code> 和一个 <code>demo02.iml</code>，和 Eclipse 那套完全对不上</em></p><p>Maven 的做法是<strong>定一套标准结构，谁都按这个来</strong>（这也是课程代码工程 <code>maven-project01</code> 的样子）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项目名/</span></span>
<span class="line"><span>├── pom.xml                 ← Maven 的核心配置文件（项目对象模型）</span></span>
<span class="line"><span>├── src/                    ← 源码目录</span></span>
<span class="line"><span>│   ├── main/               ← 主程序（PPT 里说的&quot;主程序&quot;）</span></span>
<span class="line"><span>│   │   ├── java/           ← 主程序的 Java 代码</span></span>
<span class="line"><span>│   │   └── resources/      ← 主程序用到的配置文件</span></span>
<span class="line"><span>│   └── test/               ← 测试程序（PPT 里说的&quot;测试程序&quot;）</span></span>
<span class="line"><span>│       ├── java/           ← 测试代码</span></span>
<span class="line"><span>│       └── resources/      ← 测试用的配置文件</span></span>
<span class="line"><span>└── target/                 ← 构建产物（编译输出、打好的 jar 包都在这儿，由 Maven 生成）</span></span></code></pre></div><div class="important custom-block github-alert"><p class="custom-block-title">重要</p><p><code>src/main</code> 和 <code>src/test</code> 的分家是 Maven 项目结构的重点：<strong>主程序放 <code>main</code>、测试程序放 <code>test</code></strong>。除了打包时测试代码不会被打进去，更重要的是&quot;测试代码和业务代码分开&quot;——这正是后面讲 JUnit 单元测试时反复强调的优点。</p></div><h2 id="核心概念-一张图看懂-maven" tabindex="-1">核心概念：一张图看懂 Maven <a class="header-anchor" href="#核心概念-一张图看懂-maven" aria-label="Permalink to &quot;核心概念：一张图看懂 Maven&quot;">​</a></h2><p>PPT 第 19 页把前面这些概念画成了一张图（<strong>pom.xml → 项目对象模型 / 依赖管理模型 → 构建生命周期与阶段 → 插件 → 仓库</strong>），这是这一章最该记住的一张：</p><p><img src="https://img.tsh520.cn/file/blog/article/19-Maven%E6%A0%B8%E5%BF%83%E6%A6%82%E5%BF%B5%E5%9B%BE.jpg" alt="Maven核心概念图"><em>图：Maven 的核心概念图（PPT 第 19 页；原页是 PPT 里用图形拼的矢量图，这里按原样导成图片）——左边 <code>pom.xml</code> 是入口，蓝色框里装着 POM、依赖管理模型、构建生命周期/阶段和五个&quot;插件&quot;，右上是仓库，最下面一排是这些插件作用到的东西（源文件与 jar 包）</em></p><p>按从左到右的顺序，五个概念各说一句话：</p><table tabindex="0"><thead><tr><th>概念</th><th>英文</th><th>一句话理解</th><th>在哪儿看得见</th></tr></thead><tbody><tr><td><strong>项目对象模型</strong></td><td>POM（Project Object Model）</td><td>Maven 把项目抽象成一个对象，<strong><code>pom.xml</code> 就是这个模型</strong>：项目的坐标、依赖、打包方式、插件全写在里面</td><td>项目根目录的 <code>pom.xml</code></td></tr><tr><td><strong>依赖管理模型</strong></td><td>Dependency</td><td>用<strong>坐标</strong>（groupId + artifactId + version）声明依赖，Maven 负责去仓库取、去管版本冲突</td><td><code>pom.xml</code> 里的 <code>&lt;dependencies&gt;</code></td></tr><tr><td><strong>构建生命周期/阶段</strong></td><td>Build lifecycle &amp; phases</td><td>把&quot;构建&quot;抽象成一串<strong>有顺序的阶段</strong>（clean、compile、test、package、install、deploy…），<strong>跑后面的阶段会自动把前面的跑一遍</strong></td><td><code>mvn</code> 命令、IDEA 右侧 Maven 面板</td></tr><tr><td><strong>插件</strong></td><td>Plugin</td><td><strong>每个阶段真正干活的执行者</strong>：编译靠编译插件、跑测试靠 surefire 插件、打包靠 jar 插件……</td><td>IDEA Maven 面板的 Plugins 列表 / <code>pom.xml</code> 的 <code>&lt;build&gt;</code></td></tr><tr><td><strong>仓库</strong></td><td>Repository</td><td>存放资源（各种 jar 包）的地方，依赖就是从这里来的</td><td>本地仓库目录、私服、中央仓库</td></tr></tbody></table><p>&quot;阶段&quot;和&quot;插件&quot;的关系，在真实的 IDEA Maven 面板里一眼就能看出来——左边是<strong>阶段</strong>（Lifecycle），右边那串是<strong>插件</strong>（Plugins），点阶段其实就是在调插件：</p><p><img src="https://img.tsh520.cn/file/blog/article/47-%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%E9%98%B6%E6%AE%B5%E4%B8%8E%E6%8F%92%E4%BB%B6%E9%9D%A2%E6%9D%BF.jpg" alt="生命周期阶段与插件面板"><em>图：IDEA 右侧 Maven 面板（PPT 第 47 页）——Lifecycle 里列的是 <code>clean</code>、<code>validate</code>、<code>compile</code>、<code>test</code>、<code>package</code>、<code>verify</code>、<code>install</code>、<code>site</code>、<code>deploy</code> 这些阶段；Plugins 里列的是 <code>clean</code>、<code>compiler</code>、<code>deploy</code>、<code>install</code>、<code>jar</code>、<code>resources</code>、<code>site</code>、<code>surefire</code> 这些插件，括号里是插件的坐标和版本</em></p><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p>这张图里的&quot;阶段&quot;下一层怎么排、每个阶段到底做什么，是后面生命周期那一篇的内容；这一篇只要记住<strong>这几个概念是配合起来工作的</strong>：<code>pom.xml</code> 描述项目 → 依赖模型从仓库取 jar → 命令触发生命周期阶段 → 阶段由插件执行。</p></div><h2 id="仓库-jar-包放在哪里" tabindex="-1">仓库：jar 包放在哪里 <a class="header-anchor" href="#仓库-jar-包放在哪里" aria-label="Permalink to &quot;仓库：jar 包放在哪里&quot;">​</a></h2><p>PPT 第 20 页在概念图旁边专门画了仓库这一块：</p><p><img src="https://img.tsh520.cn/file/blog/article/20-Maven%E4%B8%89%E7%B1%BB%E4%BB%93%E5%BA%93%E5%9B%BE.jpg" alt="Maven三类仓库图"><em>图：Maven 的仓库体系（PPT 第 20 页）——左边是 pom.xml 和它驱动的构建过程（生命周期/阶段 + 插件），右边是三类仓库：本地仓库、中央仓库、远程仓库（私服），它们之间由箭头连起来表示依赖从哪儿取</em></p><p><strong>仓库：用于存储资源，管理各种 jar 包。</strong> 一共三类：</p><table tabindex="0"><thead><tr><th>仓库</th><th>PPT 的定义</th><th>谁维护</th></tr></thead><tbody><tr><td><strong>本地仓库</strong></td><td>自己计算机上的一个目录</td><td>你自己（装 Maven 时可以指定路径，下一篇就配这个）</td></tr><tr><td><strong>中央仓库</strong></td><td>由 Maven 团队维护的<strong>全球唯一</strong>的仓库</td><td>Maven 官方团队，地址 &lt;<a href="https://repo1.maven.org/maven2/" target="_blank" rel="noreferrer">https://repo1.maven.org/maven2/</a>&gt;</td></tr><tr><td><strong>远程仓库（私服）</strong></td><td>一般由<strong>公司团队搭建</strong>的私有仓库</td><td>公司（团队内部的 jar 不能放公网，就放这里）</td></tr></tbody></table><p>找依赖（jar）的顺序是 PPT 第 21 页那组&quot;必答问答&quot;的重点，<strong>三步走</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 本地仓库 ──没有──▶ ② 远程仓库（私服） ──没有──▶ ③ 中央仓库</span></span>
<span class="line"><span>     │                                                   │</span></span>
<span class="line"><span>     └──────── 下载到的 jar 会存进本地仓库，下次直接用 ◀────┘</span></span></code></pre></div><ol><li><strong>本地仓库（1）</strong>：先看自己电脑上的仓库目录里有没有，有就直接用；</li><li><strong>远程仓库（2）</strong>：本地没有就问<strong>私服</strong>（公司搭的），它通常还能代理中央仓库；</li><li><strong>中央仓库（3）</strong>：私服也没有（或者没配私服），最后才去<strong>中央仓库</strong>找；</li><li>找到之后下载的 jar 会<strong>存回本地仓库</strong>，下次就不用再远程取了——这也是&quot;第一次建项目慢、之后快&quot;的原因。</li></ol><h3 id="这一节的-必答问答" tabindex="-1">这一节的&quot;必答问答&quot; <a class="header-anchor" href="#这一节的-必答问答" aria-label="Permalink to &quot;这一节的&quot;必答问答&quot;&quot;">​</a></h3><p>PPT 第 21 页是一页问答页，三个问题正好把这一节收口，<strong>这是要能直接答出来的</strong>：</p><table tabindex="0"><thead><tr><th>PPT 的问题</th><th>答案</th></tr></thead><tbody><tr><td>Maven 中的仓库用来存储什么的?</td><td><strong>jar 包</strong>（存储和管理各种 jar 包 / 资源）</td></tr><tr><td>Maven 中有哪几类仓库?</td><td><strong>本地仓库</strong>、<strong>远程仓库（私服）</strong>、<strong>中央仓库</strong></td></tr><tr><td>查找依赖（jar）的顺序是什么样的?</td><td>本地仓库（<strong>1</strong>）→ 远程仓库（<strong>2</strong>）→ 中央仓库（<strong>3</strong>）</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>中央仓库地址单独记一下：<strong>&lt;<a href="https://repo1.maven.org/maven2/" target="_blank" rel="noreferrer">https://repo1.maven.org/maven2/</a>&gt;</strong>。下一篇配阿里云私服，配的就是&quot;把中央仓库换成国内镜像&quot;，因为直连中央仓库下载很慢。</p></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>Maven 是什么？</td><td><strong>一款用于管理和构建 Java 项目的工具</strong>，Apache 旗下的开源项目，<strong>基于项目对象模型（POM）</strong>，通过一小段描述信息管理项目的构建</td></tr><tr><td>Maven 有哪三大作用？</td><td><strong>依赖管理</strong>（管理 jar 包）、<strong>项目构建</strong>（标准化的跨平台自动化构建）、<strong>统一项目结构</strong>（标准统一的项目结构）</td></tr><tr><td>项目构建有哪四个动作？</td><td><strong>编译 compile</strong>、<strong>测试 test</strong>、<strong>打包 package</strong>、<strong>发布 deploy</strong></td></tr><tr><td>Maven 项目的核心配置文件是什么？</td><td>根目录下的 <strong><code>pom.xml</code></strong>（项目对象模型 POM 的载体）</td></tr><tr><td>概念图上有哪几个核心概念？</td><td><strong>POM</strong>、<strong>依赖管理模型（Dependency）</strong>、<strong>构建生命周期/阶段</strong>、<strong>插件</strong>、<strong>仓库</strong></td></tr><tr><td>仓库有哪三类？</td><td><strong>本地仓库</strong>（自己电脑上的目录）、<strong>远程仓库/私服</strong>（公司团队搭建）、<strong>中央仓库</strong>（Maven 团队维护，全球唯一，&lt;<a href="https://repo1.maven.org/maven2/" target="_blank" rel="noreferrer">https://repo1.maven.org/maven2/</a>&gt;）</td></tr><tr><td>查找依赖的顺序？</td><td><strong>本地仓库（1）→ 远程仓库（2）→ 中央仓库（3）</strong>，下载后存回本地仓库</td></tr><tr><td>Maven 的主程序、测试程序分别放哪？</td><td>主程序放 <strong><code>src/main/java</code></strong>、测试程序放 <strong><code>src/test/java</code></strong></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/posts/编程学习/javaweb学习笔记/22-实战-vueaxios员工列表/">上一篇：实战-Vue+Axios员工列表</a></li><li><a href="/posts/编程学习/javaweb学习笔记/24-maven的安装与配置/">下一篇：Maven的安装与配置</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><h3 id="一、知识回顾-读完直接做下面的实践题" tabindex="-1">一、知识回顾（读完直接做下面的实践题） <a class="header-anchor" href="#一、知识回顾-读完直接做下面的实践题" aria-label="Permalink to &quot;一、知识回顾（读完直接做下面的实践题）&quot;">​</a></h3><ol><li>Maven 的定义：<strong>一款用于管理和构建 Java 项目的工具</strong>，是 <strong>Apache 旗下的开源项目</strong>；更完整的说法是&quot;一个项目管理和构建工具，**基于项目对象模型（POM）**的概念，通过一小段描述信息来管理项目的构建&quot;，官网 <strong>&lt;<a href="http://maven.apache.org/" target="_blank" rel="noreferrer">http://maven.apache.org/</a>&gt;</strong></li><li><strong>Apache 软件基金会</strong>：成立于 <strong>1999 年 7 月</strong>，是目前世界上最大、最受欢迎的开源软件基金会，专门为支持开源项目而生的<strong>非盈利性组织</strong></li><li>Maven 的<strong>三大作用</strong>：<strong>依赖管理</strong>（方便快捷的管理项目依赖的资源 jar 包）、<strong>项目构建</strong>（标准化的跨平台 Linux/Windows/MacOS 的<strong>自动化</strong>项目构建方式）、<strong>统一项目结构</strong>（提供标准、统一的项目结构）</li><li>项目构建的四个动作及英文名：<strong>编译（compile）→ 测试（test）→ 打包（package）→ 发布（deploy）</strong></li><li><strong>POM（项目对象模型）</strong>：Maven 把项目抽象成一个对象模型，用根目录下的 <strong><code>pom.xml</code></strong> 描述项目的坐标、依赖、插件等信息，Maven 读它来构建</li><li><strong>依赖管理模型（Dependency）</strong>：用<strong>坐标</strong>声明项目需要的 jar 包，Maven 自动从仓库获取并管理</li><li><strong>构建生命周期/阶段（Build lifecycle &amp; phases）</strong>：把构建过程抽象成<strong>有顺序的阶段</strong>，<strong>同一套生命周期中运行后面的阶段时，前面的阶段都会运行</strong>；而每个阶段真正干活的是<strong>插件（Plugin）</strong>——PPT 概念图上并排画了多个&quot;插件&quot;，在 IDEA 的 Maven 面板里<strong>左边 Lifecycle 是阶段、右边 Plugins 是插件</strong></li><li><strong>仓库</strong>的定义与三类：仓库是<strong>用于存储资源、管理各种 jar 包</strong>的地方；三类是<strong>本地仓库</strong>（自己计算机上的一个目录）、<strong>远程仓库（私服）</strong>（一般由公司团队搭建的私有仓库）、<strong>中央仓库</strong>（由 Maven 团队维护的<strong>全球唯一</strong>仓库，地址 <strong>&lt;<a href="https://repo1.maven.org/maven2/" target="_blank" rel="noreferrer">https://repo1.maven.org/maven2/</a>&gt;</strong>）</li><li><strong>查找依赖的顺序</strong>：<strong>本地仓库（1）→ 远程仓库（2）→ 中央仓库（3）</strong>；找到后下载的 jar 会存进本地仓库，下次直接用</li><li>Maven 的标准项目结构与本章路线图：<strong>主程序</strong>放 <strong><code>src/main/java</code></strong>（配置文件放 <code>src/main/resources</code>），<strong>测试程序</strong>放 <strong><code>src/test/java</code></strong>（配置放 <code>src/test/resources</code>），构建产物在 <strong><code>target/</code></strong>，根目录下有 <strong><code>pom.xml</code></strong>；这一章的<strong>Maven 核心</strong> = Maven 概述 / IDEA 集成 Maven / 依赖管理 / 单元测试，<strong>Maven 进阶</strong> = 分模块设计 / 继承 / 聚合 / 私服</li></ol><h3 id="二、概念自测" tabindex="-1">二、概念自测 <a class="header-anchor" href="#二、概念自测" aria-label="Permalink to &quot;二、概念自测&quot;">​</a></h3><ul><li><p>[ ] <strong>2-1 用一句话说清&quot;Maven 是什么&quot;，并解释里面的&quot;POM&quot;指什么</strong> 要求：说出它管哪两件事（管理 / 构建），并指出 POM 在项目里对应哪个文件。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：定义里有&quot;管理和构建&quot;两个动词，还有&quot;基于……概念&quot;和&quot;一小段描述信息&quot; <strong>二级 · 角度</strong>：这个&quot;描述信息&quot;写在哪个文件里？这个文件在项目根目录叫什么名字？</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-1</strong> Maven 是一款<strong>用于管理和构建 Java 项目的工具</strong>（Apache 旗下的开源项目），它**基于项目对象模型（POM）**的概念、通过一小段描述信息来管理项目的构建。POM 在项目里对应的就是根目录下的 <strong><code>pom.xml</code></strong>——项目叫什么、依赖哪些 jar、用什么插件，全写在这一个文件里。</p></details></li><li><p>[ ] <strong>2-2 三大作用分别解决什么问题？各举一个&quot;没有 Maven 时&quot;的麻烦</strong> 要求：三条都说到，每条配一个具体场景（找 jar / 编译打包 / 目录结构）。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：从&quot;要用的第三方库&quot;&quot;把源码变成能跑的东西&quot;&quot;项目目录长什么样&quot;三个角度各想一层 <strong>二级 · 角度</strong>：依赖管理对应&quot;下载和拷 jar&quot;，项目构建对应&quot;编译/测试/打包/发布&quot;，统一项目结构对应&quot;Eclipse、MyEclipse、IDEA 各一套目录&quot;</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-2</strong> ①<strong>依赖管理</strong>：没有 Maven 要自己去官网找 commons-io、Spring 这些 jar 下载、再拷进项目的 lib 目录，版本还得自己对齐；有了 Maven 只在 <code>pom.xml</code> 里写一段坐标就完事。②<strong>项目构建</strong>：没有 Maven 得在 IDE 里手工点编译、点运行、再想办法打包；有了 Maven，<code>mvn compile / test / package / deploy</code> 这几个标准动作在 Linux、Windows、MacOS 上都能自动化跑。③<strong>统一项目结构</strong>：没有 Maven 时 Eclipse 的项目里有 <code>bin</code>、<code>.classpath</code>、<code>.project</code>，IDEA 的项目里是 <code>.iml</code>，换工具就得重新认路；有了 Maven 一律是 <code>src/main/java</code>、<code>src/test/java</code> 那一套。</p></details></li><li><p>[ ] <strong>2-3 判断并改错：依赖查找顺序是&quot;中央仓库 → 本地仓库 → 私服&quot;，对吗？</strong> 要求：先判断，再写出正确顺序，并说明为什么顺序不能反。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：想想&quot;自己电脑上的目录&quot;和&quot;要联网的仓库&quot;哪个更快、更该先看</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-3</strong> 错。正确顺序是<strong>本地仓库（1）→ 远程仓库/私服（2）→ 中央仓库（3）</strong>。顺序反了意味着每引一个依赖都要先上网找一遍——本地明明已经有了（比如上次下载过）还要联网，又慢又浪费；而且实际项目里公司内部 jar 只放在私服上，根本不走中央仓库，所以先从本地查、再问私服、最后才是中央仓库。</p></details></li><li><p>[ ] <strong>2-4 把&quot;pom.xml、依赖管理模型、构建生命周期/阶段、插件、仓库&quot;串成一段话说明它们怎么配合</strong> 要求：五个概念都用上，说清&quot;谁读谁、谁干活、谁提供资源&quot;。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：按&quot;描述项目 → 声明依赖 → 触发阶段 → 执行插件 → 取出 jar&quot;这条线走一遍 <strong>二级 · 方法</strong>：pom.xml 描述项目（POM）；<code>&lt;dependencies&gt;</code> 里是依赖管理模型；<code>mvn package</code> 触发生命周期阶段；阶段由插件执行；jar 包来自仓库</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-4</strong> Maven 读项目根目录的 <strong><code>pom.xml</code></strong>（它就是<strong>项目对象模型 POM</strong> 的载体），从中知道这个项目是什么、需要什么；项目声明的依赖写在 <strong><code>&lt;dependencies&gt;</code></strong> 里，属于<strong>依赖管理模型</strong>——靠坐标去<strong>仓库</strong>取：先看<strong>本地仓库</strong>，没有再问<strong>私服</strong>，最后才去<strong>中央仓库</strong>。要构建时，一条 <code>mvn package</code> 触发<strong>构建生命周期</strong>里的某个<strong>阶段</strong>，阶段前面的阶段会一起跑；而每个阶段真正干活的是<strong>插件</strong>（编译插件、测试插件、打包插件），最后产出 jar 包。</p></details></li></ul>`,63)])])}const m=s(e,[["render",r]]);export{h as __pageData,m as default};
